PAYLOAD = r"""{"backup.py":"\"\"\"Dedicated RESOLUTE dump / isolated restore. Never log credentials or data.\"\"\"\nimport datetime as dt\nimport hashlib\nimport importlib.util\nimport json\nimport os\nimport re\nfrom pathlib import Path\nimport subprocess\nimport tempfile\nimport time\nfrom urllib.parse import urlsplit\nfrom urllib.request import Request, urlopen\n\n_spec = importlib.util.spec_from_file_location('resolute_protection', Path(__file__).with_name('protection.py'))\nprotection = importlib.util.module_from_spec(_spec)\n_spec.loader.exec_module(protection)\n_events_spec = importlib.util.spec_from_file_location('resolute_protection_events', Path(__file__).with_name('protection_events.py'))\nprotection_events = importlib.util.module_from_spec(_events_spec)\n_events_spec.loader.exec_module(protection_events)\n\nPREFIX = 'resolute/v1/'\nPROBE = \"SELECT jsonb_agg(t ORDER BY id)::text FROM resolute_backup_probe.sample t\"\n# Read only, on the isolated restored database. Never emit member or payment IDs.\nPAYMENT_RESTORE_CHECK = \"\"\"\nSELECT json_build_object(\n 'orders', (SELECT count(*) FROM resolute_payments_sandbox.orders),\n 'grants', (SELECT count(*) FROM resolute_payments_sandbox.grants),\n 'events', (SELECT count(*) FROM resolute_payments_sandbox.events),\n 'audit', (SELECT count(*) FROM resolute_payments_sandbox.audit),\n 'alert_outbox', (SELECT count(*) FROM resolute_payments_sandbox.alert_outbox),\n 'invalid_grants', (SELECT count(*) FROM resolute_payments_sandbox.grants g\n   LEFT JOIN resolute_payments_sandbox.orders o ON o.id=g.order_id\n   WHERE o.id IS NULL OR g.user_id IS DISTINCT FROM o.user_id\n     OR o.quote->>'product' IS DISTINCT FROM 'resolute_v1'\n     OR o.quote->>'kind' IS DISTINCT FROM g.kind\n     OR o.capture_id IS NULL OR o.paid_at IS NULL\n     OR g.state IS DISTINCT FROM CASE o.state\n       WHEN 'paid' THEN 'active' WHEN 'revoked' THEN 'revoked'\n       WHEN 'suspended' THEN 'suspended' ELSE NULL END\n     OR (SELECT count(*) FROM resolute_payments_sandbox.audit a\n         WHERE a.order_id=g.order_id AND a.code='SANDBOX_ACCESS_GRANTED') <> 1),\n 'missing_grants', (SELECT count(*) FROM resolute_payments_sandbox.orders o\n   WHERE o.state='paid' AND NOT EXISTS\n     (SELECT 1 FROM resolute_payments_sandbox.grants g WHERE g.order_id=o.id))\n)::text\n\"\"\"\n\nLIVE_PAYMENT_RESTORE_CHECK = PAYMENT_RESTORE_CHECK.replace(\n    'resolute_payments_sandbox', 'resolute_payments_live').replace(\n    'SANDBOX_ACCESS_GRANTED', 'LIVE_ACCESS_GRANTED')\nLIVE_SCHEMA_CHECK = \"SELECT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='resolute_payments_live')\"\n\ndef verify_restored_payments(env, *, live=False):\n    sql = LIVE_PAYMENT_RESTORE_CHECK if live else PAYMENT_RESTORE_CHECK\n    result = json.loads(run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c', sql], env=env))\n    if result['invalid_grants'] or result['missing_grants']:\n        raise RuntimeError('restored payment ledger is inconsistent')\n    return {key: result[key] for key in ('orders', 'grants', 'events', 'audit', 'alert_outbox')}\n\ndef verify_restored_live_payments(env, *, required=False):\n    present = run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c',\n                   LIVE_SCHEMA_CHECK], env=env).decode().strip()\n    if present not in ('t', 'f'):\n        raise RuntimeError('invalid live schema presence result')\n    if present == 'f':\n        if required:\n            raise RuntimeError('required live ledger missing from backup')\n        return {'state': 'not_installed'}\n    counts = verify_restored_payments(env, live=True)\n    # The view must survive the dump/restore too, not only its underlying tables.\n    run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c',\n         'SELECT count(*) FROM resolute_payments_live.entitlement_periods'], env=env)\n    return {'state': 'verified', 'rows': counts}\n\nSQL = \"\"\"CREATE SCHEMA IF NOT EXISTS resolute_backup_probe;\nCREATE TABLE IF NOT EXISTS resolute_backup_probe.sample\n(id integer PRIMARY KEY, payload jsonb NOT NULL);\nINSERT INTO resolute_backup_probe.sample VALUES\n(1,'{\"text\":\"\u5fa9\u5143\u78ba\u8a8d RESOLUTE\",\"value\":9800,\"optional\":null}'),\n(2,'{\"text\":\"restore test\",\"value\":3980,\"optional\":true}')\nON CONFLICT (id) DO NOTHING;\"\"\"\n\ndef heartbeat(suffix=''):\n    url = os.environ.get('BACKUP_MONITOR_PING_URL', '')\n    if not url:\n        return False\n    parsed = urlsplit(url)\n    if parsed.scheme != 'https' or parsed.hostname != 'hc-ping.com':\n        raise RuntimeError('invalid monitoring endpoint')\n    try:\n        with urlopen(Request(url.rstrip('/') + suffix, data=b'', method='POST'), timeout=15):\n            return True\n    except Exception:\n        print(json.dumps({'event':'RESOLUTE_MONITOR_PING_FAILED'}), flush=True)\n        return False\n\ndef run(args, *, env=None, data=None):\n    result = subprocess.run(args, input=data, env=env, capture_output=True, timeout=600)\n    if result.returncode:\n        # stderr may contain URLs, credentials, or table data. Do not log it.\n        raise RuntimeError('command failed: ' + Path(args[0]).name)\n    return result.stdout\n\ndef psql_env():\n    e = os.environ.copy()\n    if e.get('PGDATABASE') != 'resolute' or e.get('PGHOST') != 'postgres.railway.internal':\n        raise RuntimeError('source is not the dedicated RESOLUTE database')\n    e['PGSSLMODE'] = 'require'\n    e['PGCONNECT_TIMEOUT'] = '15'\n    return e\n\ndef retained_keys(objects):\n    \"\"\"Keep newest seven successful dumps and latest in each of four ISO weeks.\"\"\"\n    ordered = sorted(objects, key=lambda x: x['Key'], reverse=True)\n    keep = set()\n    days = set()\n    for item in ordered:\n        day = Path(item['Key']).name[:8]\n        if day not in days and len(days) < 7:\n            days.add(day)\n            keep.add(item['Key'])\n    weeks = set()\n    for x in ordered:\n        date = dt.datetime.strptime(Path(x['Key']).name[:8], '%Y%m%d').date()\n        week = date.isocalendar()[:2]\n        if week in weeks:\n            continue\n        if len(weeks) == 4:\n            break\n        weeks.add(week)\n        keep.add(x['Key'])\n    return keep\n\ndef sha(path):\n    h = hashlib.sha256()\n    with path.open('rb') as f:\n        for block in iter(lambda: f.read(1024 * 1024), b''):\n            h.update(block)\n    return h.hexdigest()\n\n# Restored DB's own protection history, compared object-for-row with the store.\nPROTECTION_HISTORY_SQL = \"\"\"SELECT COALESCE(json_agg(json_build_object('userId',clerk_user_id,\n 'revision',revision,'kind',kind,'at',to_char(occurred_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'))\n ORDER BY clerk_user_id,revision,kind),'[]'::json)::text FROM resolute.protection_outbox\"\"\"\n# An event committed after the dump's snapshot is legitimately absent from the\n# restored DB. The backup manifest stamp is taken after pg_dump finishes, so a\n# bounded margin before it is allowed; anything older must have its restored row.\nBACKUP_POINT_GRACE = dt.timedelta(minutes=10)\n\n\nclass ProtectionConfigError(RuntimeError):\n    reason = 'protection-config'\n\n\ndef backup_point_cutoff(created_at):\n    if not isinstance(created_at, str) or not re.fullmatch(r'\\d{8}T\\d{12}Z', created_at):\n        raise ProtectionConfigError('backup point in time required')\n    stamp = dt.datetime.strptime(created_at, '%Y%m%dT%H%M%S%fZ').replace(tzinfo=dt.timezone.utc)\n    return stamp - BACKUP_POINT_GRACE\n\n\ndef load_online_protection(env, client_factory, config, *, db_events=None,\n                           backup_cutoff=None, state=None):\n    \"\"\"Read the isolated history store, never fall back to dump credentials.\n\n    The pinned manifest is the chain anchor (docs/RESOLUTE-PROTECTION-CHAIN.md).\n    With `state` and RESOLUTE_PROTECTION_CHAIN_WRITE=true, state['extend'] seals\n    the verified inventory as a new chained manifest; call it only after replay.\n    \"\"\"\n    names = ('ENDPOINT', 'BUCKET', 'REGION', 'ACCESS_KEY_ID', 'SECRET_ACCESS_KEY')\n    values = {name: env.get('RESOLUTE_RESTORE_PROTECTION_' + name) for name in names}\n    if any(not isinstance(value, str) or not value.strip() for value in values.values()):\n        raise ProtectionConfigError('independent protection store configuration required')\n    endpoint = urlsplit(values['ENDPOINT'])\n    if (endpoint.scheme != 'https' or not endpoint.hostname or endpoint.username\n            or endpoint.password or endpoint.query or endpoint.fragment\n            or endpoint.path not in ('', '/')):\n        raise ProtectionConfigError('invalid independent protection endpoint')\n    backup_endpoint = urlsplit(env.get('BACKUP_ENDPOINT', ''))\n    if (endpoint.netloc.lower() == backup_endpoint.netloc.lower()\n            and values['BUCKET'] == env.get('BACKUP_BUCKET')):\n        raise ProtectionConfigError('protection history must be separate from dump storage')\n    key_hex = env.get('RESOLUTE_PROTECTION_KEY_HEX', '')\n    pin = env.get('RESOLUTE_PROTECTION_EVENTS_MANIFEST_SHA256', '')\n    if (not re.fullmatch('[0-9a-f]{64}', key_hex)\n            or not re.fullmatch('[0-9a-f]{64}', pin)):\n        raise ProtectionConfigError('independent protection key and manifest pin required')\n    if db_events is None or backup_cutoff is None:\n        raise ProtectionConfigError('restored database history and backup point required')\n    write = env.get('RESOLUTE_PROTECTION_CHAIN_WRITE') or 'false'\n    if write not in ('true', 'false'):\n        raise ProtectionConfigError('invalid chain write setting')\n    client = client_factory('s3', endpoint_url=values['ENDPOINT'],\n                            aws_access_key_id=values['ACCESS_KEY_ID'],\n                            aws_secret_access_key=values['SECRET_ACCESS_KEY'],\n                            region_name=values['REGION'], config=config)\n    result = protection_events.verify_append_only(\n        client, values['BUCKET'], bytes.fromhex(key_hex), pin, protection,\n        db_events=db_events, backup_cutoff=backup_cutoff)\n    if state is not None:\n        state['chain'] = {'linked_manifests': result['linked'], 'tip_height': result['height'],\n                          'objects': len(result['objects']), 'added_since_tip': result['added'],\n                          'newer_than_backup': result['newer_than_backup'],\n                          'extended': False, 'manifest_sha256': None}\n        if write == 'true':\n            def extend():\n                now = dt.datetime.now(dt.timezone.utc)\n                sealed = now.strftime('%Y-%m-%dT%H:%M:%S.') + f'{now.microsecond // 1000:03d}Z'\n                digest = protection_events.extend_chain(client, values['BUCKET'], pin, result,\n                                                        mode='restore', sealed_at=sealed)\n                state['chain'].update(extended=digest is not None, manifest_sha256=digest)\n            state['extend'] = extend\n    return result['ledger']\n\ndef validate_restore_environment(env):\n    \"\"\"Reject source database credentials before client imports or any I/O.\n\n    PostgreSQL image metadata is harmless; all other PG variables can affect\n    libpq or a child process and must not enter the isolated restore job.\n    \"\"\"\n    image_metadata = {'PG_MAJOR', 'PG_VERSION', 'PG_SHA256', 'PGDATA'}\n    for name, value in env.items():\n        if value and ((name.startswith('PG') and name not in image_metadata)\n                      or name.endswith(('_DB_URL', 'DATABASE_URL'))\n                      or name.startswith(('DATABASE_', 'POSTGRES_'))):\n            raise RuntimeError('restore environment contains production connection variables')\n\n\ndef main():\n    mode = os.environ['RESOLUTE_BACKUP_MODE']\n    if mode not in ('bootstrap', 'backup', 'restore', 'protection-export'):\n        raise RuntimeError('invalid mode')\n    if mode == 'restore':\n        validate_restore_environment(os.environ)\n    import boto3\n    from botocore.config import Config\n    started = time.monotonic()\n    bucket = os.environ['BACKUP_BUCKET']\n    s3 = boto3.client('s3', endpoint_url=os.environ['BACKUP_ENDPOINT'],\n                     aws_access_key_id=os.environ['BACKUP_ACCESS_KEY_ID'],\n                     aws_secret_access_key=os.environ['BACKUP_SECRET_ACCESS_KEY'],\n                     region_name=os.environ['BACKUP_REGION'],\n                     config=Config(s3={'addressing_style': 'virtual'}, retries={'max_attempts': 3},\n                                   connect_timeout=15, read_timeout=120))\n    with tempfile.TemporaryDirectory(prefix='resolute-') as temp:\n        root = Path(temp)\n        dump = root / 'backup.dump'\n        encrypted = root / 'backup.dump.age'\n        if mode == 'protection-export':\n            pin = protection.export_checkpoint(s3, bucket, root, run, psql_env(),\n                os.environ['BACKUP_AGE_RECIPIENT'])\n            # Digest identifies ciphertext only; no user IDs or settings are logged.\n            print(json.dumps({'event': 'RESOLUTE_PROTECTION_EXPORTED', 'checkpoint_sha256': pin}), flush=True)\n            return\n        if mode in ('bootstrap', 'backup'):\n            e = psql_env()\n            if mode == 'bootstrap':\n                run(['psql', '-X', '-v', 'ON_ERROR_STOP=1', '-q'], env=e, data=SQL.encode())\n            probe = run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c', PROBE], env=e).decode().strip()\n            run(['pg_dump', '-Fc', '--no-owner', '--no-acl', '-f', str(dump)], env=e)\n            run(['pg_restore', '--list', str(dump)])\n            run(['age', '-r', os.environ['BACKUP_AGE_RECIPIENT'], '-o', str(encrypted), str(dump)])\n            # Avoid silently outgrowing the approved $3/month budget.\n            if encrypted.stat().st_size > 1024 ** 3:\n                raise RuntimeError('backup exceeds 1 GiB planning limit; review budget')\n            stamp = dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\n            key = PREFIX + 'dumps/' + stamp + '.dump.age'\n            manifest = {'key': key, 'dump_sha256': sha(dump), 'cipher_sha256': sha(encrypted),\n                        'bytes': encrypted.stat().st_size, 'probe': probe,\n                        'postgres_major': 18, 'created_at': stamp}\n            s3.upload_file(str(encrypted), bucket, key)\n            downloaded = root / 'readback.age'\n            s3.download_file(bucket, key, str(downloaded))\n            if sha(downloaded) != manifest['cipher_sha256']:\n                raise RuntimeError('stored backup checksum mismatch')\n            s3.put_object(Bucket=bucket, Key=key + '.json', Body=json.dumps(manifest).encode())\n            s3.put_object(Bucket=bucket, Key=PREFIX + 'latest.json', Body=json.dumps(manifest).encode())\n            objects = []\n            for page in s3.get_paginator('list_objects_v2').paginate(Bucket=bucket, Prefix=PREFIX+'dumps/'):\n                objects.extend(x for x in page.get('Contents', []) if x['Key'].endswith('.dump.age'))\n            keep = retained_keys(objects)\n            for item in objects:\n                if item['Key'] not in keep:\n                    s3.delete_object(Bucket=bucket, Key=item['Key'])\n                    s3.delete_object(Bucket=bucket, Key=item['Key'] + '.json')\n            report = {'event': 'RESOLUTE_BACKUP_OK', 'bytes': manifest['bytes'],\n                      'dump_bytes': dump.stat().st_size, 'retained': len(keep)}\n        else:\n            # Production credentials must never be present in a restore container.\n            manifest = json.loads(s3.get_object(Bucket=bucket, Key=PREFIX+'latest.json')['Body'].read())\n            if not manifest['key'].startswith(PREFIX+'dumps/'):\n                raise RuntimeError('invalid backup key')\n            s3.download_file(bucket, manifest['key'], str(encrypted))\n            if sha(encrypted) != manifest['cipher_sha256']:\n                raise RuntimeError('stored backup checksum mismatch')\n            identity = root / 'identity.txt'\n            identity.write_text(os.environ['BACKUP_AGE_IDENTITY']); identity.chmod(0o600)\n            run(['age', '-d', '-i', str(identity), '-o', str(dump), str(encrypted)])\n            if sha(dump) != manifest['dump_sha256']:\n                raise RuntimeError('decrypted dump checksum mismatch')\n            # A new independent cluster with Unix-socket-only access, no persistent volume.\n            cluster = root / 'cluster'; cluster.mkdir()\n            run(['chown', '-R', 'postgres:postgres', str(root)])\n            run(['runuser', '-u', 'postgres', '--', 'initdb', '-D', str(cluster), '-A', 'trust', '--no-locale', '--encoding=UTF8'])\n            run(['runuser', '-u', 'postgres', '--', 'pg_ctl', '-D', str(cluster), '-l', str(root/'pg.log'),\n                 '-o', \"-c listen_addresses='' -k \" + str(root), '-w', 'start'])\n            try:\n                e = os.environ.copy()\n                for k in list(e):\n                    if k.startswith('PG'): del e[k]\n                e.update(PGHOST=str(root), PGUSER='postgres', PGDATABASE='resolute_restore_test', PGSSLMODE='disable')\n                run(['createdb', 'resolute_restore_test'], env=e)\n                run(['pg_restore', '--exit-on-error', '--no-owner', '--no-acl', '-d', 'resolute_restore_test', str(dump)], env=e)\n                restored = run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c', PROBE], env=e).decode().strip()\n                if restored != manifest['probe']:\n                    raise RuntimeError('restored probe differs from backed-up data')\n                count = int(run(['psql', '-XAt', '-c', 'SELECT count(*) FROM resolute_backup_probe.sample'], env=e))\n                if count != 2: raise RuntimeError('probe row count differs')\n                payment_counts = verify_restored_payments(e)\n                live_counts = verify_restored_live_payments(\n                    e, required=os.environ.get('RESOLUTE_REQUIRE_LIVE_LEDGER') == 'true')\n                presence = run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c', protection.PRESENCE_SQL], env=e).decode().strip()\n                if presence not in ('true', 'false'):\n                    raise RuntimeError('invalid protected table presence result')\n                protection_result = {'state': 'not_installed'}\n                if presence == 'true' or os.environ.get('RESOLUTE_REQUIRE_PROTECTION') == 'true':\n                    online = run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c',\n                        \"SELECT (to_regclass('resolute.protection_outbox') IS NOT NULL)::text\"], env=e).decode().strip()\n                    if online not in ('true', 'false'):\n                        raise RuntimeError('invalid online protection schema result')\n                    if online == 'true':\n                        history = json.loads(run(['psql', '-XAt', '-v', 'ON_ERROR_STOP=1', '-c',\n                            PROTECTION_HISTORY_SQL], env=e))\n                        chain_state = {}\n                        ledger = load_online_protection(os.environ, boto3.client,\n                            Config(s3={'addressing_style': 'virtual'},\n                                   retries={'max_attempts': 3}, connect_timeout=15,\n                                   read_timeout=120),\n                            db_events=history,\n                            backup_cutoff=backup_point_cutoff(manifest.get('created_at')),\n                            state=chain_state)\n                        run(['psql', '-Xq', '-v', 'ON_ERROR_STOP=1'], env=e,\n                            data=protection.restore_sql(ledger).encode())\n                        # Only after a successful replay may the verified base grow.\n                        if 'extend' in chain_state:\n                            chain_state['extend']()\n                        protection_result = {'state':'verified', 'source':'independent_online_chain',\n                            'deletions':len(ledger['deletions']), 'suppressions':len(ledger['suppressions']),\n                            'chain':chain_state.get('chain')}\n                    else:\n                        protection_result = protection.restore_checkpoint(s3, bucket, root, run, e, identity,\n                            os.environ.get('RESOLUTE_PROTECTION_CHECKPOINT_SHA256'))\n                report = {'event': 'RESOLUTE_RESTORE_OK', 'bytes': manifest['bytes'],\n                          'probe_rows': count, 'payment_rows': payment_counts,\n                          'live_payment_ledger': live_counts,\n                          'data_protection': protection_result,\n                          'checks': ['download','decrypt','checksums','pg_restore','probe_content','primary_key','sandbox_payment_integrity']}\n                if live_counts['state'] == 'verified':\n                    report['checks'].append('live_payment_integrity')\n                # Verify restored PK rejects duplicate ID, not just column presence.\n                try:\n                    run(['psql', '-X', '-v', 'ON_ERROR_STOP=1', '-c',\n                         \"INSERT INTO resolute_backup_probe.sample VALUES (1, '{}')\"], env=e)\n                except RuntimeError:\n                    pass\n                else:\n                    raise RuntimeError('restored primary key not enforced')\n            finally:\n                run(['runuser', '-u', 'postgres', '--', 'pg_ctl', '-D', str(cluster), '-m', 'immediate', '-w', 'stop'])\n        report['seconds'] = round(time.monotonic()-started, 3)\n        report['monitor_ping_sent'] = heartbeat()\n        print(json.dumps(report), flush=True)\n\ndef entrypoint():\n    notify_monitor = False\n    try:\n        if os.environ.get('RESOLUTE_BACKUP_MODE') == 'restore':\n            validate_restore_environment(os.environ)\n        notify_monitor = os.environ.get('RESOLUTE_BACKUP_MODE') != 'protection-export'\n        if notify_monitor:\n            heartbeat('/start')\n        main()\n    except Exception as exc:\n        if notify_monitor:\n            heartbeat('/fail')\n        # No exception details: third-party errors can embed secret material.\n        # Only a fixed, allowlisted reason code is added for diagnosis.\n        report = {'event':'RESOLUTE_JOB_FAILED','error_type':type(exc).__name__}\n        reason = getattr(exc, 'reason', None)\n        if isinstance(reason, str) and reason in protection_events.REASONS:\n            report['reason'] = reason\n        print(json.dumps(report), flush=True)\n        raise SystemExit(1)\n\n\nif __name__ == '__main__':\n    entrypoint()\n","protection.py":"\"\"\"Independent encrypted recovery checkpoint. No online-write durability claim.\n\nA restore pin must come from a write-fenced, complete export, independently of the\nDB backup. Never infer completeness/freshness from a timestamp or latest pointer.\n\"\"\"\nimport datetime as dt\nimport hashlib\nimport json\nimport re\n\nPREFIX = 'resolute/protection/v1/'  # Outside rotating dump retention.\nMAX_BYTES = 16 * 1024 * 1024\nPRESENCE_SQL = \"SELECT (to_regclass('resolute.plans') IS NOT NULL OR to_regclass('resolute.notification_settings') IS NOT NULL)::text\"\nEXPORT_SQL = \"\"\"BEGIN;\n-- Explicit maintenance export only: both writers must be unable to reconnect and\n-- no other source connection may still have an open/in-flight mutation.\nDO $$ BEGIN\n IF current_database() <> 'resolute' THEN RAISE EXCEPTION 'Dedicated database required'; END IF;\n IF (SELECT count(*) FROM pg_roles WHERE rolname IN\n   ('resolute_plan_writer','resolute_notification_writer') AND NOT rolcanlogin) <> 2\n OR EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid())\n THEN RAISE EXCEPTION 'Exclusive write-fenced maintenance required'; END IF;\nEND $$;\nLOCK TABLE resolute.plans,resolute.plan_deletions,resolute.notification_settings,\n resolute.notification_suppressions IN SHARE MODE;\nSELECT json_build_object('version',1,\n 'deletions', COALESCE((SELECT json_agg(json_build_object('userId',clerk_user_id,\n 'revision',revision,'at',to_char(deleted_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'))\n ORDER BY clerk_user_id,revision) FROM resolute.plan_deletions),'[]'::json),\n 'suppressions', COALESCE((SELECT json_agg(json_build_object('userId',clerk_user_id,\n 'revision',revision,'kind',kind,'at',to_char(stopped_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'))\n ORDER BY clerk_user_id,revision,kind) FROM resolute.notification_suppressions),'[]'::json))::text;\nCOMMIT;\"\"\"\n\ndef validate(value):\n    if not isinstance(value, dict) or set(value) != {'version', 'deletions', 'suppressions'} or type(value['version']) is not int or value['version'] != 1:\n        raise ValueError('invalid protection checkpoint')\n    for group in ('deletions', 'suppressions'):\n        if not isinstance(value[group], list):\n            raise ValueError('invalid protection checkpoint')\n        seen = set()\n        for row in value[group]:\n            keys = {'userId', 'revision', 'at'} | ({'kind'} if group == 'suppressions' else set())\n            if not isinstance(row, dict) or set(row) != keys:\n                raise ValueError('invalid protection entry')\n            if not isinstance(row['userId'], str) or not re.fullmatch(r'user_[A-Za-z0-9]{1,128}', row['userId']):\n                raise ValueError('invalid protection identity')\n            if type(row['revision']) is not int or not 0 < row['revision'] < 9007199254740991:\n                raise ValueError('invalid protection revision')\n            if not isinstance(row['at'], str) or not re.fullmatch(r'\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z', row['at']):\n                raise ValueError('invalid protection timestamp')\n            dt.datetime.fromisoformat(row['at'].replace('Z', '+00:00'))\n            if group == 'suppressions' and row['kind'] not in ('alerts', 'morning'):\n                raise ValueError('invalid protection kind')\n            key = (row['userId'], row['revision'], row.get('kind'))\n            if key in seen:\n                raise ValueError('duplicate protection entry')\n            seen.add(key)\n    return value\n\ndef load_json(raw):\n    if len(raw) > MAX_BYTES:\n        raise ValueError('protection checkpoint too large')\n    def unique(pairs):\n        result = {}\n        for key, value in pairs:\n            if key in result:\n                raise ValueError('duplicate protection field')\n            result[key] = value\n        return result\n    return validate(json.loads(raw, object_pairs_hook=unique))\n\ndef export_checkpoint(s3, bucket, root, run, source_env, recipient):\n    \"\"\"Explicit maintenance operation; caller must fence application writes first.\n\n    SQL is a single MVCC statement; retry by exporting again after a failed upload.\n    Returned ciphertext pin is usable only after the caller verifies the write fence.\n    No dump latest pointer, retention, runtime activation, or source data is changed.\n    \"\"\"\n    raw = run(['psql', '-XqAt', '-v', 'ON_ERROR_STOP=1', '-c', EXPORT_SQL], env=source_env)\n    body = json.dumps(load_json(raw), sort_keys=True, separators=(',', ':')).encode()\n    plain, encrypted = root / 'protection.json', root / 'protection.age'\n    plain.write_bytes(body); plain.chmod(0o600)\n    run(['age', '-r', recipient, '-o', str(encrypted), str(plain)])\n    cipher = encrypted.read_bytes()\n    if len(cipher) > MAX_BYTES:\n        raise ValueError('encrypted protection checkpoint too large')\n    pin = hashlib.sha256(cipher).hexdigest()\n    s3.put_object(Bucket=bucket, Key=PREFIX + pin + '.age', Body=cipher)\n    readback = s3.get_object(Bucket=bucket, Key=PREFIX + pin + '.age')['Body'].read(MAX_BYTES + 1)\n    if readback != cipher:\n        raise RuntimeError('protection readback mismatch')\n    return pin\n\ndef restore_sql(ledger):\n    validate(ledger)\n    # Validated identifiers/timestamps contain no SQL escapes. JSON is still quoted\n    # explicitly; use stdin, never shell interpolation or command-line member data.\n    payload = json.dumps(ledger, separators=(',', ':')).replace(\"'\", \"''\")\n    return \"\"\"BEGIN;\nDO $$ BEGIN\n IF current_database() <> 'resolute_restore_test' THEN\n  RAISE EXCEPTION 'Isolated restore database required'; END IF;\nEND $$;\nCREATE TEMP TABLE protection_input (body jsonb) ON COMMIT DROP;\nINSERT INTO protection_input VALUES ('\"\"\" + payload + \"\"\"'::jsonb);\n-- A checkpoint older/incomplete relative to even the dump's own journals cannot\n-- be accepted. Exact timestamp agreement also rejects conflicting history.\nDO $$ BEGIN\n IF EXISTS (SELECT 1 FROM resolute.plan_deletions d WHERE NOT EXISTS (\n  SELECT 1 FROM protection_input,LATERAL jsonb_array_elements(body->'deletions') r\n  WHERE r->>'userId'=d.clerk_user_id AND (r->>'revision')::bigint=d.revision\n   AND (r->>'at')::timestamptz=date_trunc('milliseconds',d.deleted_at)))\n OR EXISTS (SELECT 1 FROM resolute.notification_suppressions s WHERE NOT EXISTS (\n  SELECT 1 FROM protection_input,LATERAL jsonb_array_elements(body->'suppressions') r\n  WHERE r->>'userId'=s.clerk_user_id AND (r->>'revision')::bigint=s.revision\n   AND r->>'kind'=s.kind AND (r->>'at')::timestamptz=date_trunc('milliseconds',s.stopped_at)))\n THEN RAISE EXCEPTION 'Incomplete or conflicting independent checkpoint'; END IF;\nEND $$;\n-- Recovery must not run the source journaling trigger or duplicate journal keys.\nALTER TABLE resolute.notification_settings DISABLE TRIGGER USER;\nINSERT INTO resolute.plans(clerk_user_id,revision,plan,created_at,updated_at,deleted_at)\n SELECT DISTINCT ON (r->>'userId') r->>'userId',(r->>'revision')::bigint,NULL,NULL,NULL,(r->>'at')::timestamptz\n FROM protection_input, LATERAL jsonb_array_elements(body->'deletions') r\n ORDER BY r->>'userId',(r->>'revision')::bigint DESC\n ON CONFLICT(clerk_user_id) DO UPDATE SET revision=EXCLUDED.revision,\n plan=NULL,created_at=NULL,updated_at=NULL,deleted_at=EXCLUDED.deleted_at\n WHERE resolute.plans.revision <= EXCLUDED.revision;\n-- Determine both channels against the ORIGINAL restored revision, not a revision\n-- already raised by the other channel. Later explicit re-consent is preserved.\nCREATE TEMP TABLE protection_stops ON COMMIT DROP AS\n SELECT r->>'userId' AS user_id, max((r->>'revision')::bigint) AS revision,\n max((r->>'at')::timestamptz) AS stopped_at,\n bool_or(r->>'kind'='alerts' AND COALESCE(s.revision,0)<=(r->>'revision')::bigint) AS alerts,\n bool_or(r->>'kind'='morning' AND COALESCE(s.revision,0)<=(r->>'revision')::bigint) AS morning\n FROM protection_input, LATERAL jsonb_array_elements(body->'suppressions') r\n LEFT JOIN resolute.notification_settings s ON s.clerk_user_id=r->>'userId'\n GROUP BY r->>'userId';\nINSERT INTO resolute.notification_settings(clerk_user_id,settings,revision,updated_at)\n SELECT user_id,'{\"deliveryHourJst\":7,\"alertsEnabled\":false,\"morningEnabled\":false,\"watchItems\":[],\"surgeCapPct\":null}'::jsonb,\n revision,stopped_at FROM protection_stops\n ON CONFLICT(clerk_user_id) DO NOTHING;\nUPDATE resolute.notification_settings s SET\n settings=s.settings || jsonb_build_object(\n 'alertsEnabled',CASE WHEN p.alerts THEN false ELSE (s.settings->>'alertsEnabled')::boolean END,\n 'morningEnabled',CASE WHEN p.morning THEN false ELSE (s.settings->>'morningEnabled')::boolean END),\n revision=GREATEST(s.revision,p.revision),updated_at=GREATEST(s.updated_at,p.stopped_at)\n FROM protection_stops p WHERE s.clerk_user_id=p.user_id AND (p.alerts OR p.morning);\n-- Rebuild journals too so the next export cannot lose pre-restore protections.\nINSERT INTO resolute.plan_deletions\n SELECT r->>'userId',(r->>'revision')::bigint,(r->>'at')::timestamptz\n FROM protection_input,LATERAL jsonb_array_elements(body->'deletions') r\n ON CONFLICT(clerk_user_id,revision) DO NOTHING;\nINSERT INTO resolute.notification_suppressions\n SELECT r->>'userId',(r->>'revision')::bigint,r->>'kind',(r->>'at')::timestamptz\n FROM protection_input,LATERAL jsonb_array_elements(body->'suppressions') r\n ON CONFLICT(clerk_user_id,revision,kind) DO NOTHING;\n-- A restored unsent task is never safe to replay: provider acceptance may have\n-- happened after the dump. Clear payloads; future delivery needs reconciliation.\nDELETE FROM resolute.notification_outbox WHERE accepted_at IS NULL;\nALTER TABLE resolute.notification_settings ENABLE TRIGGER USER;\nCOMMIT;\"\"\"\n\ndef restore_checkpoint(s3, bucket, root, run, env, identity, pin):\n    if not isinstance(pin, str) or not re.fullmatch('[0-9a-f]{64}', pin):\n        raise RuntimeError('independent write-fenced protection checkpoint required')\n    cipher = s3.get_object(Bucket=bucket, Key=PREFIX + pin + '.age')['Body'].read(MAX_BYTES + 1)\n    if len(cipher) > MAX_BYTES or hashlib.sha256(cipher).hexdigest() != pin:\n        raise RuntimeError('protection checkpoint checksum mismatch')\n    encrypted, plain = root / 'restore-protection.age', root / 'restore-protection.json'\n    encrypted.write_bytes(cipher)\n    run(['age', '-d', '-i', str(identity), '-o', str(plain), str(encrypted)])\n    ledger = load_json(plain.read_bytes())\n    run(['psql', '-Xq', '-v', 'ON_ERROR_STOP=1'], env=env, data=restore_sql(ledger).encode())\n    return {'state': 'verified', 'deletions': len(ledger['deletions']),\n            'suppressions': len(ledger['suppressions']), 'pending_outbox': 'cleared'}\n","protection_events.py":"\"\"\"Immutable online records; seal a manifest only after fencing all writers.\n\nRestore verification is append-only (see docs/RESOLUTE-PROTECTION-CHAIN.md): the\npinned anchor manifest and every chained manifest linked back to it must still be\npresent byte-for-byte; additional objects must be authentic events that the\nrestored database also records (or that are newer than the backup).\n\"\"\"\nimport datetime as dt\nimport hashlib\nimport hmac\nimport json\nimport re\nPREFIX = 'resolute/protection/events-v1/'\nMANIFEST_PREFIX = 'resolute/protection/manifests-v1/'\nCHAIN_PREFIX = 'resolute/protection/manifests-v2/'\nMAX_OBJECTS = 100000\nMAX_CHAIN_MANIFESTS = 5000\nMAX_MANIFEST_BYTES = 32 * 1024 * 1024\n# Fixed, non-secret diagnostics for RESOLUTE_JOB_FAILED. Never add data to them.\nREASONS = frozenset({\n    'listing-incomplete', 'listing-invalid', 'inventory-missing-object',\n    'inventory-modified-object', 'inventory-unknown-event', 'inventory-db-mismatch',\n    'inventory-changed', 'chain-anchor-unreadable', 'chain-anchor-invalid',\n    'chain-invalid', 'chain-write-failed', 'protection-config'})\n\n\nclass InventoryError(ValueError):\n    \"\"\"Fail-closed protection error carrying one fixed reason code.\"\"\"\n    def __init__(self, reason, message):\n        if reason not in REASONS:\n            raise AssertionError('unknown reason code')\n        super().__init__(message)\n        self.reason = reason\n\ndef object_key(event,key):\n    identity=f\"resolute-event-v1\\n{event['userId']}\\n{event['kind']}\\n{event['revision']}\".encode()\n    return PREFIX+hmac.new(key,identity,hashlib.sha256).hexdigest()+'.bin'\n\ndef decrypt_event(body,key,name,protection):\n    return _ledger(decrypt_raw_event(body,key,name,protection),protection)\n\ndef decrypt_raw_event(body,key,name,protection):\n    from cryptography.hazmat.primitives.ciphers.aead import AESGCM\n    if len(key)!=32 or not 33<=len(body)<=2048 or body[:4]!=b'RPE1':\n        raise ValueError('invalid encrypted protection event')\n    raw=AESGCM(key).decrypt(body[4:16],body[32:]+body[16:32],name.encode())\n    def unique(pairs):\n        result={}\n        for k,v in pairs:\n            if k in result: raise ValueError('duplicate event field')\n            result[k]=v\n        return result\n    event=json.loads(raw,object_pairs_hook=unique)\n    if not isinstance(event,dict) or set(event)!={'version','userId','revision','kind','at'} or type(event['version']) is not int or event['version']!=1:\n        raise ValueError('invalid protection event')\n    if event['kind'] not in ('delete','alerts_off','morning_off'): raise ValueError('invalid protection kind')\n    _ledger(event,protection)\n    if object_key(event,key)!=name: raise ValueError('protection event identity mismatch')\n    return event\n\ndef _ledger(event,protection):\n    kind=event['kind']\n    marker={k:event[k] for k in ('userId','revision','at')}\n    ledger={'version':1,'deletions':[],'suppressions':[]}\n    if kind=='delete': ledger['deletions'].append(marker)\n    else: ledger['suppressions'].append(dict(marker,kind=kind.removesuffix('_off')))\n    return protection.validate(ledger)\n\ndef inventory(s3,bucket):\n    return _listing(s3,bucket,PREFIX,r'[0-9a-f]{64}\\.bin',33,2048,MAX_OBJECTS)\n\ndef _listing(s3,bucket,prefix,pattern,min_size,max_size,limit):\n    items={};complete=False\n    for page in s3.get_paginator('list_objects_v2').paginate(Bucket=bucket,Prefix=prefix):\n        # Exhausting an iterator is not proof that the provider returned every\n        # page. Require an explicit final page before sealing or restoring.\n        if complete or type(page.get('IsTruncated')) is not bool:\n            raise InventoryError('listing-incomplete','invalid protection inventory pagination')\n        complete=not page['IsTruncated']\n        if not complete and (not isinstance(page.get('NextContinuationToken'),str) or not page['NextContinuationToken']):\n            raise InventoryError('listing-incomplete','incomplete protection inventory pagination')\n        for item in page.get('Contents',[]):\n            name=item['Key']\n            if not re.fullmatch(re.escape(prefix)+pattern,name) or name in items or not min_size<=item['Size']<=max_size:\n                raise InventoryError('listing-invalid','invalid protection inventory')\n            items[name]={'size':item['Size'],'etag':item['ETag']}\n            if len(items)>limit: raise InventoryError('listing-invalid','protection inventory exceeds reviewed limit')\n    if not complete: raise InventoryError('listing-incomplete','incomplete protection inventory pagination')\n    return items\n\ndef read_object(s3,bucket,name,limit):\n    # Bounded reads may leave unread bytes on failure. Always release the HTTP\n    # response, including when the provider raises during streaming.\n    stream=s3.get_object(Bucket=bucket,Key=name)['Body']\n    try:\n        return stream.read(limit)\n    finally:\n        stream.close()\n\ndef seal_manifest(s3,bucket,key,protection):\n    before=inventory(s3,bucket);objects=[]\n    for name in sorted(before):\n        body=read_object(s3,bucket,name,2049)\n        decrypt_event(body,key,name,protection)\n        objects.append({'key':name,'sha256':hashlib.sha256(body).hexdigest()})\n    if inventory(s3,bucket)!=before: raise ValueError('protection inventory changed; fence writers first')\n    body=json.dumps({'version':1,'objects':objects},sort_keys=True,separators=(',',':')).encode()\n    pin=hashlib.sha256(body).hexdigest()\n    s3.put_object(Bucket=bucket,Key=MANIFEST_PREFIX+pin+'.json',Body=body)\n    if read_object(s3,bucket,MANIFEST_PREFIX+pin+'.json',len(body)+1)!=body:\n        raise ValueError('protection manifest readback mismatch')\n    return pin\n\ndef load_manifest(s3,bucket,key,pin,protection,*,require_complete_inventory=False):\n    if not isinstance(pin,str) or not re.fullmatch('[0-9a-f]{64}',pin):\n        raise ValueError('independent online protection manifest required')\n    raw=read_object(s3,bucket,MANIFEST_PREFIX+pin+'.json',32*1024*1024+1)\n    if len(raw)>32*1024*1024 or hashlib.sha256(raw).hexdigest()!=pin:\n        raise ValueError('protection manifest checksum mismatch')\n    manifest=json.loads(raw)\n    if not isinstance(manifest,dict) or set(manifest)!={'version','objects'} or type(manifest['version']) is not int or manifest['version']!=1 or not isinstance(manifest['objects'],list) or len(manifest['objects'])>MAX_OBJECTS:\n        raise ValueError('invalid protection manifest')\n    # A pinned manifest may be authentic but stale. Live-store restore must also\n    # reject omitted/new objects and concurrent inventory changes. Operators must\n    # still fence writers: two observations cannot prevent a later write.\n    before=inventory(s3,bucket) if require_complete_inventory else None\n    ledger={'version':1,'deletions':[],'suppressions':[]};seen=set()\n    for item in manifest['objects']:\n        if not isinstance(item,dict) or set(item)!={'key','sha256'} or not isinstance(item['key'],str) or not re.fullmatch(re.escape(PREFIX)+r'[0-9a-f]{64}\\.bin',item['key']) or not isinstance(item['sha256'],str) or not re.fullmatch('[0-9a-f]{64}',item['sha256']) or item['key'] in seen:\n            raise ValueError('invalid protection manifest entry')\n        seen.add(item['key'])\n        body=read_object(s3,bucket,item['key'],2049)\n        if hashlib.sha256(body).hexdigest()!=item['sha256']: raise ValueError('protection event checksum mismatch')\n        event=decrypt_event(body,key,item['key'],protection)\n        for group in ('deletions','suppressions'):ledger[group].extend(event[group])\n    if before is not None and (seen!=set(before) or inventory(s3,bucket)!=before):\n        raise ValueError('incomplete or changing protection inventory; fence writers and reseal manifest')\n    return protection.validate(ledger)\n\n# --- Append-only chain verification (weekly restore) -------------------------\n\n_SHA = re.compile('[0-9a-f]{64}')\n_TIME = '%Y-%m-%dT%H:%M:%S.%fZ'\n_KINDS = ('delete','alerts_off','morning_off')\n\ndef canonical(value):\n    \"\"\"Byte-identical to Node JSON.stringify with sorted keys (ASCII content).\"\"\"\n    return json.dumps(value,sort_keys=True,separators=(',',':')).encode()\n\ndef _parse_objects(objects,*,ordered):\n    if not isinstance(objects,list) or len(objects)>MAX_OBJECTS: raise ValueError('objects')\n    result={};last=''\n    for item in objects:\n        if (not isinstance(item,dict) or set(item)!={'key','sha256'} or not isinstance(item['key'],str)\n                or not re.fullmatch(re.escape(PREFIX)+r'[0-9a-f]{64}\\.bin',item['key'])\n                or not isinstance(item['sha256'],str) or not _SHA.fullmatch(item['sha256'])\n                or item['key'] in result or (ordered and item['key']<=last)):\n            raise ValueError('entry')\n        last=item['key'];result[item['key']]=item['sha256']\n    return result\n\ndef _read_manifest(s3,bucket,name,digest,raw=None):\n    if raw is None: raw=read_object(s3,bucket,name,MAX_MANIFEST_BYTES+1)\n    if len(raw)>MAX_MANIFEST_BYTES or hashlib.sha256(raw).hexdigest()!=digest: raise ValueError('checksum')\n    def unique(pairs):\n        result={}\n        for k,v in pairs:\n            if k in result: raise ValueError('duplicate manifest field')\n            result[k]=v\n        return result\n    return json.loads(raw,object_pairs_hook=unique)\n\ndef load_anchor(s3,bucket,pin):\n    \"\"\"The pinned, write-fenced version 1 manifest that every chain starts from.\"\"\"\n    if not isinstance(pin,str) or not _SHA.fullmatch(pin):\n        raise InventoryError('protection-config','independent online protection manifest required')\n    try:\n        raw=read_object(s3,bucket,MANIFEST_PREFIX+pin+'.json',MAX_MANIFEST_BYTES+1)\n    except Exception as error:\n        raise InventoryError('chain-anchor-unreadable','protection anchor manifest unreadable') from error\n    try:\n        manifest=_read_manifest(s3,bucket,None,pin,raw)\n        if (not isinstance(manifest,dict) or set(manifest)!={'version','objects'}\n                or type(manifest['version']) is not int or manifest['version']!=1):\n            raise ValueError('shape')\n        return _parse_objects(manifest['objects'],ordered=False)\n    except Exception as error:\n        raise InventoryError('chain-anchor-invalid','invalid protection anchor manifest') from error\n\ndef _chain_objects(manifest,pin):\n    if (not isinstance(manifest,dict) or set(manifest)!={'version','anchor','previous','height','mode','sealedAt','objects'}\n            or type(manifest['version']) is not int or manifest['version']!=2\n            or not isinstance(manifest['anchor'],str) or not _SHA.fullmatch(manifest['anchor'])\n            or not isinstance(manifest['previous'],str) or not _SHA.fullmatch(manifest['previous'])\n            or type(manifest['height']) is not int or not 0<manifest['height']<=MAX_CHAIN_MANIFESTS\n            or manifest['mode'] not in ('restore','maintenance') or not isinstance(manifest['sealedAt'],str)):\n        raise ValueError('shape')\n    dt.datetime.strptime(manifest['sealedAt'],_TIME)\n    objects=_parse_objects(manifest['objects'],ordered=True)\n    if manifest['anchor']!=pin: return None\n    if (manifest['height']==1)!=(manifest['previous']==pin): raise ValueError('height')\n    return objects\n\ndef load_chain(s3,bucket,pin):\n    \"\"\"Anchor objects plus every chained manifest that links back to the pin.\n\n    Each chained manifest records its predecessor's SHA256 and height and must\n    contain every predecessor object with an identical checksum. Manifests are\n    content-addressed, so rewriting history changes their name. Manifests of a\n    different anchor are ignored; malformed or unlinked ones fail closed.\n    \"\"\"\n    anchor=load_anchor(s3,bucket,pin)\n    listed=_listing(s3,bucket,CHAIN_PREFIX,r'[0-9a-f]{64}\\.json',2,MAX_MANIFEST_BYTES,MAX_CHAIN_MANIFESTS)\n    found={}\n    for name in sorted(listed):\n        digest=name[len(CHAIN_PREFIX):-len('.json')]\n        try:\n            raw=read_object(s3,bucket,name,MAX_MANIFEST_BYTES+1)\n            manifest=_read_manifest(s3,bucket,name,digest,raw)\n            # Writers emit canonical bytes only; anything else is not ours.\n            if canonical(manifest)!=raw: raise ValueError('non-canonical manifest')\n            objects=_chain_objects(manifest,pin)\n        except Exception as error:\n            raise InventoryError('chain-invalid','invalid chained protection manifest') from error\n        if objects is not None: found[digest]=(manifest,objects)\n    linked={pin:(0,anchor)}\n    for digest,(manifest,objects) in sorted(found.items(),key=lambda x:(x[1][0]['height'],x[0])):\n        parent=linked.get(manifest['previous'])\n        if parent is None or parent[0]+1!=manifest['height']:\n            raise InventoryError('chain-invalid','chained manifest does not link back to the anchor')\n        if any(objects.get(k)!=v for k,v in parent[1].items()):\n            raise InventoryError('chain-invalid','chained manifest is not append-only')\n        linked[digest]=(manifest['height'],objects)\n    expected={}\n    for _,objects in linked.values():\n        for k,v in objects.items():\n            if expected.setdefault(k,v)!=v: raise InventoryError('chain-invalid','conflicting chained manifests')\n    # Deterministic tip: greatest height, then smallest digest. Every linked\n    # manifest (including any fork) is verified through `expected` regardless.\n    tip=max(linked,key=lambda d:(linked[d][0],[-ord(c) for c in d]))\n    return {'anchor':anchor,'expected':expected,'tip':tip,'height':linked[tip][0],\n            'tip_objects':linked[tip][1],'linked':len(linked)-1}\n\ndef _database_history(rows):\n    if not isinstance(rows,list): raise InventoryError('inventory-db-mismatch','invalid database history')\n    result={}\n    for row in rows:\n        if (not isinstance(row,dict) or set(row)!={'userId','revision','kind','at'}\n                or row['kind'] not in _KINDS or not isinstance(row['at'],str)):\n            raise InventoryError('inventory-db-mismatch','invalid database history')\n        identity=(row['userId'],row['revision'],row['kind'])\n        if identity in result: raise InventoryError('inventory-db-mismatch','duplicate database history')\n        result[identity]=row['at']\n    return result\n\ndef verify_append_only(s3,bucket,key,pin,protection,*,db_events,backup_cutoff):\n    \"\"\"Accept the live inventory only if it extends the sealed chain.\n\n    (a) every object in the anchor and in every linked chained manifest is still\n    present with an identical SHA256; (b) every object authenticates as an event\n    under its own object key; (c) every non-anchor event has its exact restored\n    protection_outbox row or is strictly newer than backup_cutoff, and every\n    restored row has its event; (d) listing is explicitly complete, and nothing\n    listed disappears or changes while it is read. Anything else fails closed.\n    \"\"\"\n    if not isinstance(backup_cutoff,dt.datetime) or backup_cutoff.tzinfo is None:\n        raise InventoryError('protection-config','backup point in time required')\n    database=_database_history(db_events)\n    chain=load_chain(s3,bucket,pin)\n    before=inventory(s3,bucket)\n    if any(name not in before for name in chain['expected']):\n        raise InventoryError('inventory-missing-object','sealed protection object missing')\n    objects=[];stored={};ledger={'version':1,'deletions':[],'suppressions':[]};newer=0\n    for name in sorted(before):\n        body=read_object(s3,bucket,name,2049)\n        digest=hashlib.sha256(body).hexdigest()\n        if name in chain['expected'] and chain['expected'][name]!=digest:\n            raise InventoryError('inventory-modified-object','sealed protection object changed')\n        try:\n            event=decrypt_raw_event(body,key,name,protection)\n        except Exception as error:\n            raise InventoryError('inventory-unknown-event','unauthenticated protection object') from error\n        identity=(event['userId'],event['revision'],event['kind'])\n        recorded=database.get(identity)\n        if recorded is not None and recorded!=event['at']:\n            raise InventoryError('inventory-db-mismatch','protection event conflicts with database history')\n        if recorded is None and name not in chain['anchor']:\n            at=dt.datetime.strptime(event['at'],_TIME).replace(tzinfo=dt.timezone.utc)\n            if at<=backup_cutoff:\n                raise InventoryError('inventory-db-mismatch','protection event missing from database history')\n            newer+=1\n        stored[identity]=event['at']\n        objects.append({'key':name,'sha256':digest})\n        part=_ledger(event,protection)\n        for group in ('deletions','suppressions'): ledger[group].extend(part[group])\n    if any(stored.get(identity)!=at for identity,at in database.items()):\n        raise InventoryError('inventory-db-mismatch','database history missing from protection store')\n    after=inventory(s3,bucket)\n    for name,meta in before.items():\n        if name not in after: raise InventoryError('inventory-missing-object','protection object disappeared')\n        if after[name]!=meta: raise InventoryError('inventory-changed','protection object changed during read')\n    protection.validate(ledger)\n    return {'ledger':ledger,'objects':objects,'tip':chain['tip'],'height':chain['height'],\n            'tip_objects':chain['tip_objects'],'linked':chain['linked'],\n            'added':sum(1 for item in objects if item['key'] not in chain['tip_objects']),\n            'newer_than_backup':newer}\n\ndef chain_manifest(pin,previous,height,objects,mode,sealed_at):\n    body=canonical({'version':2,'anchor':pin,'previous':previous,'height':height,'mode':mode,\n                    'sealedAt':sealed_at,'objects':objects})\n    if len(body)>MAX_MANIFEST_BYTES: raise InventoryError('chain-write-failed','chained manifest too large')\n    return hashlib.sha256(body).hexdigest(),body\n\ndef extend_chain(s3,bucket,pin,result,*,mode,sealed_at):\n    \"\"\"Write a new content-addressed chained manifest; never overwrite one.\n\n    Returns None (nothing written) when the verified inventory equals the tip.\n    \"\"\"\n    if {o['key']:o['sha256'] for o in result['objects']}==result['tip_objects']:\n        return None\n    digest,body=chain_manifest(pin,result['tip'],result['height']+1,result['objects'],mode,sealed_at)\n    name=CHAIN_PREFIX+digest+'.json'\n    try:\n        s3.put_object(Bucket=bucket,Key=name,Body=body,ContentType='application/json',\n                      **({'IfNoneMatch':'*'} if _supports_if_none_match(s3) else {}))\n    except Exception as error:\n        # An existing object at this content address is fine only if identical;\n        # the readback below proves that either way.\n        if not _precondition_failed(error):\n            raise InventoryError('chain-write-failed','chained manifest write failed') from error\n    try:\n        readback=read_object(s3,bucket,name,len(body)+1)\n    except Exception as error:\n        raise InventoryError('chain-write-failed','chained manifest readback failed') from error\n    if readback!=body: raise InventoryError('chain-write-failed','chained manifest readback mismatch')\n    return digest\n\ndef _supports_if_none_match(s3):\n    try: return 'IfNoneMatch' in s3.meta.service_model.operation_model('PutObject').input_shape.members\n    except Exception: return False\n\ndef _precondition_failed(error):\n    response=getattr(error,'response',None)\n    return isinstance(response,dict) and response.get('ResponseMetadata',{}).get('HTTPStatusCode')==412\n"}"""

MODULES = ('backup.py', 'protection.py', 'protection_events.py')
MAX_PAYLOAD = 4 * 1024 * 1024


class LauncherError(RuntimeError):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


def canonical(mapping):
    return json.dumps(mapping, sort_keys=True, separators=(',', ':')).encode()


def load_modules():
    if not (COMMIT and EXPECTED_MODE and MODULES_SHA256 and PAYLOAD):
        raise LauncherError('launcher-unbuilt')
    if os.environ.get('RESOLUTE_BACKUP_MODE') != EXPECTED_MODE:
        raise LauncherError('launcher-mode')
    try:
        if len(PAYLOAD) > MAX_PAYLOAD:
            raise ValueError('payload too large')
        body = PAYLOAD.encode('ascii')
        if hashlib.sha256(body).hexdigest() != MODULES_SHA256:
            raise ValueError('digest mismatch')
        mapping = json.loads(body)
        if not isinstance(mapping, dict) or sorted(mapping) != sorted(MODULES):
            raise ValueError('module set')
        for name in MODULES:
            if not isinstance(mapping[name], str):
                raise ValueError('module type')
            compile(mapping[name], name, 'exec')
        if canonical(mapping) != body:
            raise ValueError('non-canonical payload')
    except Exception:
        raise LauncherError('launcher-bundle') from None
    return mapping


def extract(mapping):
    workdir = tempfile.mkdtemp(prefix='resolute-job-')
    try:
        os.chmod(workdir, 0o700)
        for name in MODULES:
            fd = os.open(os.path.join(workdir, name), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
                handle.write(mapping[name])
        written = {}
        for name in MODULES:
            with open(os.path.join(workdir, name), encoding='utf-8', newline='') as handle:
                written[name] = handle.read()
        if hashlib.sha256(canonical(written)).hexdigest() != MODULES_SHA256:
            raise LauncherError('launcher-bundle')
    except BaseException:
        shutil.rmtree(workdir, ignore_errors=True)
        raise
    return workdir


def fail_ping():
    # Same rule as backup.py heartbeat(): https://hc-ping.com only, URL never logged.
    if os.environ.get('RESOLUTE_BACKUP_MODE') == 'protection-export':
        return
    url = os.environ.get('BACKUP_MONITOR_PING_URL', '')
    parsed = urlsplit(url)
    if not url or parsed.scheme != 'https' or parsed.hostname != 'hc-ping.com':
        return
    try:
        with urlopen(Request(url.rstrip('/') + '/fail', data=b'', method='POST'), timeout=15):
            pass
    except Exception:
        print(json.dumps({'event': 'RESOLUTE_MONITOR_PING_FAILED'}), flush=True)


def fail(exc, reason):
    fail_ping()
    print(json.dumps({'event': 'RESOLUTE_JOB_FAILED', 'error_type': type(exc).__name__,
                      'reason': reason}), flush=True)
    raise SystemExit(1)


def main():
    workdir = None
    try:
        try:
            mapping = load_modules()
            workdir = extract(mapping)
        except LauncherError as exc:
            fail(exc, exc.reason)
        except Exception as exc:
            fail(exc, 'launcher-extract')
        print(json.dumps({'event': 'RESOLUTE_PROTECTED_BUNDLE_READY', 'commit': COMMIT,
                          'sha256': MODULES_SHA256, 'modules': len(MODULES),
                          'mode': EXPECTED_MODE}), flush=True)
        script = os.path.join(workdir, 'backup.py')
        saved_argv = sys.argv[:]
        sys.argv = [script]
        try:
            # backup.py's entrypoint sends /start and /fail itself and exits 1 on
            # failure; that SystemExit passes through unchanged.
            runpy.run_path(script, run_name='__main__')
        except Exception as exc:
            # Only reached when backup.py fails before its entrypoint (e.g. import).
            fail(exc, 'launcher-run')
        finally:
            sys.argv = saved_argv
    finally:
        if workdir:
            shutil.rmtree(workdir, ignore_errors=True)


if __name__ == '__main__':
    main()
